/** Welcome panel shown once, right after a pupil signs in. */
function pupil_welcome(array $u):void{
 if(empty($_SESSION['pupil_welcome']))return;unset($_SESSION['pupil_welcome']);
 $pid=(int)$u['id'];$s=progress_stats($pid);$h=(int)date('G');$greet=$h<12?'Good morning':($h<18?'Good afternoon':'Good evening');
 $first=explode(' ',trim($u['name']))[0];$next=next_learning_lesson($pid);$streak=(int)$s['current_streak'];
 $msg=$streak>1?'You are on a '.$streak.'-day reading streak. Keep it going!':($s['completed']?'Welcome back! Let’s read a little more today.':'Your reading adventure starts today!');
 echo '<div class="pw-overlay" data-welcome role="dialog" aria-modal="true" aria-labelledby="pw-title"><div class="pw-panel">';
 echo '<button type="button" class="pw-close" data-welcome-close aria-label="Close">'.icon('close').'</button>';
 echo '<div class="pw-art" aria-hidden="true"><svg viewBox="0 0 320 210" width="320" height="210"><circle cx="160" cy="104" r="92" fill="url(#pwg-glow)"/><path d="M-90 178q130-40 250-10t250-6v48H-90z" fill="#d7ecce"/><path d="M-90 192q140-18 260-4t240-4v26H-90z" fill="#b5dca5"/><g class="pw-rays" stroke="#f6c02c" stroke-width="4" stroke-linecap="round"><path d="M48 6v8M48 66v8M14 40h8M74 40h8M24 16l6 6M66 58l6 6M24 64l6-6M66 22l6-6"/></g><circle class="pw-sun" cx="48" cy="40" r="20" fill="url(#pwg-sun)"/><path d="M41 38q2-3 4 0M51 38q2-3 4 0M42 45q6 5 12 0" stroke="#b36b00" stroke-width="2" stroke-linecap="round" fill="none"/><g class="pw-cloud"><path d="M62 70a12 12 0 0 1 20-10 14 14 0 0 1 26 4 9 9 0 0 1 2 18H66a10 10 0 0 1-4-12z" fill="#fff"/></g><g class="pw-cloud pw-cloud2"><path d="M262 92a9 9 0 0 1 15-7 11 11 0 0 1 20 3 7 7 0 0 1 1 14h-33a8 8 0 0 1-3-10z" fill="#fff"/></g><g class="pw-flower"><path d="M34 196v-14" stroke="#4c9a52" stroke-width="2.5"/><circle cx="34" cy="179" r="5" fill="#ff8fab"/><circle cx="34" cy="179" r="2" fill="#f6c02c"/></g><g class="pw-flower pw-fl2"><path d="M286 194v-13" stroke="#4c9a52" stroke-width="2.5"/><circle cx="286" cy="178" r="5" fill="#f6c02c"/><circle cx="286" cy="178" r="2" fill="#fff"/></g><g class="pw-flower pw-fl3"><path d="M64 200v-10" stroke="#4c9a52" stroke-width="2.5"/><circle cx="64" cy="188" r="4" fill="#9ad0ff"/><circle cx="64" cy="188" r="1.6" fill="#fff"/></g><ellipse cx="160" cy="196" rx="44" ry="6" fill="#1d6b36" opacity=".18"/>'.PF_KID.'<g class="pw-bubble"><rect x="200" y="8" width="102" height="34" rx="17" fill="#fff" stroke="#f6c02c" stroke-width="2.5"/><path d="M212 40l-14 10 24-10" fill="#fff" stroke="#f6c02c" stroke-width="2.5" stroke-linejoin="round"/><rect x="210" y="34" width="16" height="6" fill="#fff"/><text x="251" y="30" text-anchor="middle" font-family="Poppins,sans-serif" font-weight="700" font-size="14" fill="#17633a">Let’s read!</text></g><g class="pw-fly pw-f1"><text x="198" y="114" font-family="Poppins,sans-serif" font-weight="700" font-size="18" fill="#2f8a4b">A</text></g><g class="pw-fly pw-f2"><text x="216" y="110" font-family="Poppins,sans-serif" font-weight="700" font-size="17" fill="#d6452f">b</text></g><g class="pw-fly pw-f3"><path d="M208 96l3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1z" fill="#f6c02c"/></g><g class="pw-fly pw-f4"><path d="M232 104l2 5 5 1-4 4 1 5-4-3-5 3 1-5-4-4 5-1z" fill="#ffb02e"/></g><g class="pw-fly pw-f5"><text x="240" y="122" font-family="Poppins,sans-serif" font-weight="700" font-size="15" fill="#3b82c4">c</text></g><g class="pw-sparkle"><path d="M102 122l2 6 6 2-6 2-2 6-2-6-6-2 6-2z" fill="#f6c02c"/><path d="M252 152l1.6 4.4 4.4 1.6-4.4 1.6-1.6 4.4-1.6-4.4-4.4-1.6 4.4-1.6z" fill="#2f8a4b"/><path d="M288 60l1.4 3.6 3.6 1.4-3.6 1.4-1.4 3.6-1.4-3.6-3.6-1.4 3.6-1.4z" fill="#ff8fab"/><path d="M116 30l1.4 3.6 3.6 1.4-3.6 1.4-1.4 3.6-1.4-3.6-3.6-1.4 3.6-1.4z" fill="#9ad0ff"/></g></svg></div>';
 echo '<span class="pw-eyebrow">'.e(strtoupper($greet)).'</span><h2 id="pw-title">Hi, '.e($first).'!</h2><p class="pw-msg">'.e($msg).'</p>';
 echo '<div class="pw-stats"><span class="pw-stat">'.icon('bolt').'<b>'.(int)$s['xp'].'</b> XP</span><span class="pw-stat">'.icon('fire').'<b>'.$streak.'</b> day'.($streak===1?'':'s').'</span><span class="pw-stat">'.icon('star').'<b>'.(int)$s['completed'].'</b> lesson'.((int)$s['completed']===1?'':'s').' done</span></div>';
 echo '<div class="pw-actions">'.($next?'<a class="btn primary" href="?page=lesson&amp;id='.(int)$next['id'].'">'.icon('book').'Continue: '.e(mb_strimwidth(lesson_display_label((int)$next['level_id'],(int)$next['position']).($next['subtitle']?' · '.$next['subtitle']:''),0,46,'…')).'</a>':'').'<button type="button" class="btn secondary" data-welcome-close>Go to my dashboard</button></div>';
 echo '</div></div>';
}
